responsePreview:
This Terraform configuration creates an AWS S3 bucket named `sample` and enables bucket versioning using the dedicated `aws_s3_bucket_versioning` resource. The versioning configuration includes `expected_bucket_owner = "123456789012"` to ensure the bucket ownership matches the expected AWS account ID.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "sample" {
  bucket = "sample"
}

resource "aws_s3_bucket_versioning" "sample" {
  bucket                = aws_s3_bucket.sample.id
  expected_bucket_owner = "123456789012"

  versioning_configuration {
    status = "Enabled"
  }
}
```
